1	// Shard selection for cache keys. See README for the contract with the routing table.
2	
3	// FNV-1a, 32-bit, folded to a signed integer like the routing table stores it.
4	export function hashKey(key: string): number {
5	  let h = 0x811c9dc5;
6	  for (let i = 0; i < key.length; i++) {
7	    h ^= key.charCodeAt(i);
8	    h = Math.imul(h, 0x01000193);
9	  }
10	  return h | 0;
11	}
12	
13	// The non-negative remainder of the hash divided by shards (Python's % semantics).
14	export function shardFor(key: string, shards: number): number {
15	  if (!Number.isInteger(shards) || shards <= 0) throw new RangeError(`shards must be a positive integer, got ${shards}`);
16	  return hashKey(key) % shards;
17	}
18

